async ({ gh: { issueView, issueComment, issueClose }, shell: { execFile } }) => {
  const body = JSON.parse((await issueView(383, { json: ["body"] } as any)).stdout).body as string;
  const e = await execFile("gh", ["issue", "edit", "383", "--repo", "cv/pit", "--body", body.replaceAll("- [ ] ", "- [x] ")], { raise: true });
  const cm = await issueComment(383, "Shipped in [v0.37.0](https://github.com/cv/pit/releases/tag/v0.37.0) (release PR #388, tracked in #387). Every item above landed in #385 and #386." as any);
  const c = await issueClose(383);
  const s = JSON.parse((await issueView(383, { json: ["state", "body"] } as any)).stdout);
  return { e: e.code, cm: cm.code, c: c.code, state: s.state, unticked: (s.body.match(/- \[ \]/g) ?? []).length };
}
